def normalize(topic: str) -> str:
    """将 topic 归一化为基础表名，用于配对比较"""
    if topic.endswith("_dml"):
        return topic[:-4]
    return topic


def find_missing_topics(topic1_list: list[str], topic2_list: list[str]) -> dict:
    """
    找出 topic1 中有但 topic2 中缺失的 topic。
    规则：base 和 base_dml 视为同一组，只要 topic2 中存在任一即算存在。

    Returns:
        {
            "completely_missing": [...],   # 基础表和 _dml 均缺失
            "dml_only_missing": [...]      # 基础表存在但缺 _dml
        }
    """
    # 构建 topic2 的归一化集合（记录哪些基础表在 topic2 中存在）
    topic2_base_set = set()
    topic2_has_dml = set()

    for t in topic2_list:
        base = normalize(t)
        topic2_base_set.add(base)
        if t.endswith("_dml"):
            topic2_has_dml.add(base)

    completely_missing = []
    dml_only_missing = []

    for t in topic1_list:
        base = normalize(t)

        # 跳过 _dml 条目，只以基础表为单位进行判断，避免重复计数
        if t.endswith("_dml"):
            continue

        if base not in topic2_base_set:
            # 基础表本身就不存在于 topic2
            completely_missing.append(t)
        elif base not in topic2_has_dml:
            # 基础表存在，但缺少对应的 _dml
            dml_only_missing.append(f"{t}_dml")

    return {
        "completely_missing": sorted(completely_missing),
        "dml_only_missing": sorted(dml_only_missing),
    }


